[{{Code74k.ts - KickLang}}] 

namespace Code74k {

export enum NodeType {
    Entity,
    Relation,
    Attribute,
    Literal,
    Category,
    Context,
    Constraint,
    Logic,
    Math,
    Set,
    Text,
    Time,
    Graph,
    Map,
    Meta,
    Program,
    Query,
    Schema,
    Script,
    UI,
    User,
    // ... add more as needed
}

export enum EdgeType {
    IsA,
    PartOf,
    RelatedTo,
    HasA,
    // ... add more as needed
}

export enum DataType {
    String,
    Number,
    Boolean,
    Date,
    Object,
    Array,
    Null,
    // ... add more as needed
}

export interface Node {
    id: string;
    type: NodeType;
    name: string;
    description?: string;
    properties: { [key: string]: any };
    incoming: Edge[];
    outgoing: Edge[];
}

export interface Edge {
    id: string;
    type: EdgeType;
    source: string;
    target: string;
    properties: { [key: string]: any };
}

export interface Graph {
    nodes: Node[];
    edges: Edge[];
    metadata: { [key: string]: any };
}

} // namespace Code74k
